func TestForm(t *testing.T) {
	for k, c := range formCases {
		m, ok, err := Step(c.state, c.in)
		if c.overflow {
			if !errors.Is(err, ErrOverflow) {
				t.Errorf("case %d (%s %+v): err %v, want overflow", k, c.state, c.in, err)
			}
			continue
		}
		if err != nil || ok != c.ok {
			t.Errorf("case %d (%s %+v): ok %v err %v, want ok %v (row %d)", k, c.state, c.in, ok, err, c.ok, c.row)
			continue
		}
		if !ok {
			continue
		}
		want := rows[c.row]
		want.Args = c.args
		if !reflect.DeepEqual(m, want) {
			t.Errorf("case %d (%s %+v): move %+v, want %+v", k, c.state, c.in, m, want)
		}
	}
}

func TestStates(t *testing.T) {
	if Terminal(StateJudge) != false {
		t.Errorf("Terminal(%q)", StateJudge)
	}
	if Terminal(StateAlive) != true {
		t.Errorf("Terminal(%q)", StateAlive)
	}
	if Terminal(StateWait) != true {
		t.Errorf("Terminal(%q)", StateWait)
	}
	if Terminal(StateHung) != true {
		t.Errorf("Terminal(%q)", StateHung)
	}
	if Terminal(StateHungMoved) != true {
		t.Errorf("Terminal(%q)", StateHungMoved)
	}
	if Terminal(StateUnsure) != true {
		t.Errorf("Terminal(%q)", StateUnsure)
	}
	if Terminal(StateUnsureMoved) != true {
		t.Errorf("Terminal(%q)", StateUnsureMoved)
	}
	if Terminal(StateMove) != true {
		t.Errorf("Terminal(%q)", StateMove)
	}
	if Terminal(StateRelease) != true {
		t.Errorf("Terminal(%q)", StateRelease)
	}
	if Initial != StateJudge {
		t.Errorf("Initial %q", Initial)
	}
	if _, _, err := Step("no-such-state", In{}); err == nil {
		t.Error("Step on an unknown state")
	}
}

type record struct {
	calls []string
	args  [][]any
}

func (r *record) Result(a0 string, a1 string) error {
	r.calls = append(r.calls, "result")
	r.args = append(r.args, []any{a0, a1})
	return nil
}

func (r *record) JudgeToRelease(in In) error {
	r.calls = append(r.calls, "-JudgeToRelease")
	r.args = append(r.args, []any{})
	return nil
}

// TestApply — Apply calls exactly the action of each row once (a YOURS procedure by its method).
func TestApply(t *testing.T) {
	for _, c := range formCases {
		m, ok, err := Step(c.state, c.in)
		if !ok || err != nil {
			continue
		}
		r := &record{}
		if err := Apply(r, c.in, m); err != nil {
			t.Fatalf("row %d: Apply: %v", m.Row, err)
		}
		want := m.Action
		if want == "" {
			want = "-" + m.Proc
		}
		if len(r.calls) != 1 || r.calls[0] != want || (m.Action != "" && !reflect.DeepEqual(r.args[0], m.Args)) {
			t.Fatalf("row %d: calls %v %v, want %s %v", m.Row, r.calls, r.args, want, m.Args)
		}
	}
	if err := Apply(&record{}, In{}, Move{Row: 99}); err == nil {
		t.Error("Apply of an empty move")
	}
}
